import React from 'react';
import SectionQuestBoard from '../shared/SectionQuestBoard';
import type { OperationsQuest, OperationsQuestBoard as QuestBoard } from '../../utils/operationsQuests';
import type { SectionQuest } from '../../utils/sectionQuests';
import {
  MSME_OPS_QUEST_SUBTITLE,
  MSME_OPS_QUEST_TITLE,
} from '../../constants/msmeSimplifiedUi';

type OperationsQuestBoardProps = {
  board: QuestBoard;
  onFocusQuest?: (quest: OperationsQuest) => void;
  onSavePicture?: () => void;
  saving?: boolean;
};

const OperationsQuestBoard: React.FC<OperationsQuestBoardProps> = ({
  board,
  onFocusQuest,
  onSavePicture,
  saving = false,
}) => (
  <SectionQuestBoard
    board={board}
    title={MSME_OPS_QUEST_TITLE}
    subtitle={MSME_OPS_QUEST_SUBTITLE}
    completeMessage="All quests complete — open Advanced only if a buyer wants unit-level Scope detail."
    ariaLabel="Operations quests"
    onFocusQuest={
      onFocusQuest
        ? (quest: SectionQuest) => onFocusQuest(quest as OperationsQuest)
        : undefined
    }
    primaryAction={
      onSavePicture
        ? {
            label: 'Save picture',
            onClick: onSavePicture,
            loading: saving,
          }
        : undefined
    }
  />
);

export default OperationsQuestBoard;
